-- Phase 5 follow-up data update (see docs/decisions.md): market-based base prices for the active cars,
-- corrected car types, seats, years, fuel and features, full descriptions for all vehicles and packages.
-- Data only (no schema change). Undo: database/undo/017_phase5_data_update_undo.sql
SET NAMES utf8mb4;
UPDATE `tblvehicles` SET `PricePerDay` = 5000, `LeatherSeats` = NULL, `VehiclesOverview` = 'Suzuki\'s tall hatchback is made for the city. The upright seats are easy to get in and out of, the big windows give a clear view in traffic, and the short body fits into small parking spaces around Kathmandu.\n\nThe small petrol engine is light on fuel and the steering is easy at low speeds. Four adults sit comfortably, and the boot takes a couple of cabin bags or the weekly shopping.\n\nBest for: daily errands, commuting and short trips around the valley. For long highway drives with luggage, a sedan or an SUV is more comfortable.' WHERE `id` = 1;
UPDATE `tblvehicles` SET `PricePerDay` = 10000, `VehiclesOverview` = 'BMW\'s executive sedan: quiet, smooth and roomy, with an automatic gearbox, leather seats and a large boot that swallows airport luggage.\n\nIt feels most at home on the highway, where it is relaxed and composed at speed, and it makes an impression at weddings and business meetings.\n\nBest for: business travel, special occasions and comfortable drives on good roads. It sits low, so keep to paved roads.' WHERE `id` = 2;
UPDATE `tblvehicles` SET `PricePerDay` = 10000, `ModelYear` = 2018, `VehiclesOverview` = 'Audi\'s flagship SUV pairs a sporty, coupe-like roofline with a full five-seat cabin. Quattro all-wheel drive and an automatic gearbox make it sure-footed in the rain and on hill roads.\n\nThe cabin is finished in leather with a quiet, refined ride, and the boot is big enough for a family\'s luggage.\n\nBest for: special occasions, business travel and comfortable long drives, including hill roads in good condition.' WHERE `id` = 3;
UPDATE `tblvehicles` SET `PricePerDay` = 7000, `CarType` = 'SUV', `AntiLockBrakingSystem` = 1, `PowerSteering` = 1, `DriverAirbag` = 1, `CentralLocking` = 1, `PowerDoorLocks` = 1, `VehiclesOverview` = 'A compact SUV with a high driving position and generous ground clearance, which makes Kathmandu\'s potholes and speed breakers far easier to deal with.\n\nThere are five seats, a practical boot for a family weekend, and a petrol engine that is easy to drive in town and relaxed on the highway.\n\nBest for: small families, trips outside the valley and roads that are not always smooth.' WHERE `id` = 4;
UPDATE `tblvehicles` SET `PricePerDay` = 10000, `CarType` = 'Coupe', `SeatingCapacity` = 4, `VehiclesOverview` = 'Nissan\'s legendary sports car: a 3.8-litre twin-turbo V6 with about 570 PS, all-wheel drive and a six-speed dual-clutch automatic gearbox.\n\nIt is a 2+2. There are two proper seats in front, and the two small rear seats are best for short trips or bags. The boot is small and the car sits low to the ground.\n\nBest for: special occasions, photo shoots and smooth roads. Not suited to family trips, lots of luggage, or rough and mountain roads.' WHERE `id` = 5;
UPDATE `tblvehicles` SET `PricePerDay` = 5000, `CarType` = 'Sedan', `FuelType` = 'Petrol', `ModelYear` = 2020, `AntiLockBrakingSystem` = 1, `VehiclesOverview` = 'A comfortable sedan known for its generous rear legroom and a large boot. The soft ride suits long drives, and the petrol engine is economical at steady highway speeds.\n\nFive people fit easily, with room for everyone\'s bags in the boot.\n\nBest for: family trips, airport runs with luggage and highway journeys such as Kathmandu to Pokhara.' WHERE `id` = 6;
UPDATE `tblvehicles` SET `PricePerDay` = 10000, `SeatingCapacity` = 7, `AirConditioner` = 1, `PowerDoorLocks` = 1, `AntiLockBrakingSystem` = 1, `BrakeAssist` = 1, `PowerSteering` = 1, `PassengerAirbag` = 1, `VehiclesOverview` = 'Toyota\'s rugged seven-seat SUV is built on a strong ladder frame with high ground clearance. That is why it is a favourite on Nepal\'s hill and mountain roads.\n\nIt has LED headlamps, automatic climate control, cruise control and a power-adjustable driver\'s seat. For safety it has seven airbags, hill assist, vehicle stability control and ABS with EBD. The third row is best for children or short trips; fold it down for a big boot.\n\nBest for: large families, groups and long trips outside the valley, including rough roads.' WHERE `id` = 7;
UPDATE `tblvehicles` SET `PricePerDay` = 7000, `CarType` = 'SUV', `AirConditioner` = 1, `PowerSteering` = 1, `DriverAirbag` = 1, `PowerWindows` = 1, `CentralLocking` = 1, `VehiclesOverview` = 'A compact SUV that is short enough for city parking but sits higher than a hatchback, with good ground clearance for broken roads and speed breakers.\n\nThere are five seats, a practical boot and easy, light controls, and Suzuki\'s large service network across Nepal gives peace of mind on longer trips.\n\nBest for: small families, trips outside the valley and everyday driving.' WHERE `id` = 8;
UPDATE `tblvehicles` SET `PricePerDay` = 7000, `VehiclesOverview` = 'The latest generation of Suzuki\'s compact SUV. Higher seating and good ground clearance make broken roads and speed breakers easier, while the 1.5-litre petrol engine is easy to drive in town.\n\nThere are five seats and a practical boot for a family weekend.\n\nBest for: small families and trips outside the valley.' WHERE `id` = 20;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'Suzuki\'s smallest car and one of the most common on Nepal\'s roads. It is light, very easy to park in narrow streets and cheap to run on its 1.0-litre petrol engine.\n\nIt seats four adults (five at a squeeze), and the boot takes a couple of small bags.\n\nBest for: one or two people and short trips in town. For highway trips with luggage, choose a sedan.' WHERE `id` = 13;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'Nepal\'s favourite hatchback: lively to drive, economical and easy to park. The 1.2-litre petrol engine pulls well on the valley\'s hills, and the cabin is comfortable for four adults.\n\nThe boot takes two medium bags.\n\nBest for: city driving and short trips out of the valley, such as Nagarkot or Dhulikhel.' WHERE `id` = 14;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'A small, well-equipped hatchback with a smooth 1.2-litre petrol engine and light, easy controls. The cabin feels roomy for its size, and the ride copes well with broken roads.\n\nIt seats four adults comfortably and has a practical boot for day bags and shopping.\n\nBest for: city driving, couples and small families on short trips.' WHERE `id` = 15;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'An electric hatchback that is quiet, smooth and very cheap to run in the city. There are no gears to change, which makes stop-and-go traffic easy.\n\nThe range covers a full day of driving around the valley; for longer trips, plan where to charge. It has five seats and a small boot.\n\nBest for: city commuting and short trips around Kathmandu.' WHERE `id` = 16;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'A modern electric hatchback with a surprisingly roomy cabin thanks to its flat floor, a large rotating touchscreen and a smooth, quiet drive. It is one of the best-selling EVs in Nepal.\n\nIts range comfortably covers day trips outside the valley. On longer routes, check where to charge before you set off.\n\nBest for: couples and small families who want a comfortable, modern car without fuel costs.' WHERE `id` = 17;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'Nepal\'s most popular compact sedan: economical, reliable and comfortable, with a separate boot that keeps luggage out of sight.\n\nThe 1.2-litre petrol engine is smooth in traffic and relaxed on the highway, and five people fit with their bags.\n\nBest for: families, airport runs and highway trips on a budget.' WHERE `id` = 18;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'A spacious mid-size sedan with one of the roomiest rear seats in its class and a large boot. It is quiet and comfortable on long drives, with a 1.5-litre petrol engine.\n\nFive adults travel in comfort, with room for everyone\'s luggage.\n\nBest for: business travel, families and highway journeys.' WHERE `id` = 19;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'One of Nepal\'s most popular mid-size SUVs, with a comfortable, well-equipped cabin, good rear space and a sizeable boot.\n\nHigh ground clearance helps on rough patches, and the petrol engine is smooth on the highway.\n\nBest for: families and longer trips outside the valley.' WHERE `id` = 21;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'A compact electric crossover with SUV-style ground clearance and upright seating, in a size that is easy to park. It is quiet, smooth and very cheap to run.\n\nIt has five seats and a practical boot. For long trips, plan where to charge.\n\nBest for: city driving and short trips outside the valley.' WHERE `id` = 22;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'A roomy electric SUV with a quick, smooth drive and a spacious, distinctive cabin. It is one of the best-selling electric SUVs in Nepal.\n\nThe range covers long day trips, and it has five seats and a good-sized boot.\n\nBest for: families who want SUV comfort without fuel costs.' WHERE `id` = 23;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'BYD\'s compact electric SUV, the most imported electric SUV in Nepal in 2026. It is easy to drive and park in the city, with higher seating than a hatchback and a practical boot.\n\nIt has five seats. On longer routes, check where to charge before you set off.\n\nBest for: city driving and short trips out of the valley.' WHERE `id` = 24;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'A modern electric SUV from Changan\'s Deepal brand, with a large touchscreen, comfortable seats and a smooth, quiet drive. It was among Nepal\'s most imported electric SUVs in 2026.\n\nIt has five seats and a practical boot. On longer routes, check where to charge before you set off.\n\nBest for: families and day trips.' WHERE `id` = 25;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'The workhorse of Nepal\'s roads: a tough diesel SUV with high ground clearance that copes with hill roads and gravel better than most cars.\n\nThere are seven seats for groups and families, and more luggage space when the third row is folded.\n\nBest for: mountain roads, group trips and routes outside the valley.' WHERE `id` = 26;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'Toyota\'s seven-seat people carrier, known for a comfortable ride and reliability on long journeys. All three rows are usable by adults, and the diesel engine is strong on highways and hills.\n\nThere is room for luggage behind the third row, and more when it is folded.\n\nBest for: families, groups, pilgrimages and long highway trips.' WHERE `id` = 27;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'Toyota\'s double-cab pickup seats five and has an open load bed for cargo, bikes or trekking gear. A strong diesel engine and high ground clearance make it happy on rough and mountain roads.\n\nBest for: adventure trips, carrying equipment and routes where the paved road ends.' WHERE `id` = 28;
UPDATE `tblvehicles` SET `VehiclesOverview` = 'A 14-seat van for groups, tours, weddings and events, with plenty of room for luggage. It is comfortable on the highway and a common sight on tourist routes across Nepal.\n\nIt is offered with a driver only, because in Nepal a van of this size needs a heavier licence category than a regular car licence.\n\nBest for: group tours, family events and airport pickups for large groups.' WHERE `id` = 29;
UPDATE `tblpackages` SET `Description` = 'Your driver tracks your flight and waits in arrivals with a name board, then takes you straight to your hotel or home in Kathmandu, Lalitpur or Bhaktapur. Drop-offs are timed so you reach the terminal with room to spare.\n\nChoose the vehicle that fits your group and luggage: a hatchback for one or two travellers, a sedan for a family, an SUV for extra bags or a van for groups. Share your flight number in the request so the driver can follow any delay. The price is per vehicle, one way.' WHERE `id` = 1;
UPDATE `tblpackages` SET `Description` = 'Land in Pokhara and head to Lakeside, or fly into Bhairahawa and go straight on to Lumbini. The price is fixed, so there\'s no haggling at the terminal.\n\nPokhara International Airport is a short drive from Lakeside. Gautam Buddha International Airport in Bhairahawa is under an hour from Lumbini. Share your flight details in the request so the driver is waiting when you land. The price is per vehicle, one way.' WHERE `id` = 2;
UPDATE `tblpackages` SET `Description` = 'Book a clean, air-conditioned car for a single trip across town, whether it\'s a meeting, a hospital visit or a family dinner. The fare is agreed upfront and there\'s no meter.\n\nThe fare covers one trip of up to 15 km inside Kathmandu valley or Pokhara, which is enough for most journeys across town. Longer rides are charged per extra kilometre. Add your pickup time and both addresses to the request.' WHERE `id` = 3;
UPDATE `tblpackages` SET `Description` = 'Set your own stops and the driver waits while you finish each one. It suits a busy half day around the valley.\n\nThe booking covers 4 hours and 40 km of driving inside the valley, with fuel and tolls included. If your day runs longer, overtime is charged by the hour. It works well for bank visits, shopping, school runs or a couple of meetings across town.' WHERE `id` = 4;
UPDATE `tblpackages` SET `Description` = 'Plan meetings, family visits or a shopping run without worrying about taxis or parking. The driver stays with you from morning to evening.\n\nThe booking covers 8 hours and 80 km inside the valley, with fuel and tolls included. Overtime is charged by the hour, and a night charge applies after 8 PM. Plan your stops in advance or change them on the day.' WHERE `id` = 5;
UPDATE `tblpackages` SET `Description` = 'See the temples, stupas and royal squares that define Kathmandu, with a driver who knows the shortcuts and the best parking. You set the pace at each site.\n\nThe route takes in Pashupatinath, Boudhanath, Bhaktapur Durbar Square, Patan and Swayambhunath. Start early to beat the traffic and the midday heat. The driver drops you at each entrance and waits while you explore. Entry fees are paid at each site, and a guide is not included.' WHERE `id` = 6;
UPDATE `tblpackages` SET `Description` = 'You\'re picked up before dawn and reach the ridge in time for sunrise over the mountains. On the way back you stop at the valley\'s oldest temple and are home before lunch.\n\nPickup is at about 4:30 AM, so you reach the viewpoint before sunrise; on a clear morning the Himalayan range stretches across the horizon. After breakfast you stop at Changunarayan, a UNESCO-listed temple. Bring a warm layer: the ridge is cold at dawn.' WHERE `id` = 7;
UPDATE `tblpackages` SET `Description` = 'Drive along the Trishuli river to Kurintar, ride the cable car up to the hilltop temple for darshan, and be back in Kathmandu by evening. It works well for families with elders.\n\nThe drive to Kurintar takes about 3 to 4 hours each way along the Prithvi Highway. Cable car tickets and puja items are bought on site. Leave early on Saturdays and festival days, when the queues at the temple are longest.' WHERE `id` = 8;
UPDATE `tblpackages` SET `Description` = 'Take the scenic Prithvi Highway with a tea stop in Bandipur. Spend a day on Sarangkot, the caves, the waterfalls and Phewa Lake, then drive home at your own pace.\n\nDay 1 runs from Kathmandu to Pokhara with a tea stop in Bandipur. Day 2 is for Sarangkot at sunrise, Davis Falls, Gupteshwor Cave, the World Peace Pagoda and Phewa Lake. On day 3 you drive back to Kathmandu. The driver\'s food and accommodation are included, so there is nothing extra to pay on the road. You book your own hotel.' WHERE `id` = 9;
UPDATE `tblpackages` SET `Description` = 'Drive down to the edge of Chitwan National Park and keep the car on standby for local outings while you do your safari. You head back to Kathmandu on the third day.\n\nSauraha is about 5 hours from Kathmandu. Safaris inside the national park are run by licensed park operators, so the car takes you to and from them, and to the Tharu village and the river bank at sunset. The driver\'s food and accommodation are included. You book your own hotel.' WHERE `id` = 10;
UPDATE `tblpackages` SET `Description` = 'Stroll the old bazaar and catch the Himalayan sunset from Tundikhel. The next morning, explore a cave or nearby village before driving home.\n\nBandipur is about 4 hours from Kathmandu, just off the Prithvi Highway. The old bazaar is closed to cars, so the driver parks at the edge of town. On day 2 you can visit Siddha Cave or walk to Ramkot village before the drive home. The driver\'s food and accommodation are included.' WHERE `id` = 11;
UPDATE `tblpackages` SET `Description` = 'Arrive in Lumbini in time for a quiet evening at the Maya Devi Temple. Spend a full day among the international monasteries, then visit the ancient palace ruins at Tilaurakot on the way home.\n\nLumbini is a long day\'s drive from Kathmandu, so day 1 is mostly on the road. Day 2 is spent in the Monastic Zone, at the World Peace Pagoda and the museum. On day 3 you visit the ancient ruins at Tilaurakot on the way home. The driver\'s food and accommodation are included. You book your own hotel.' WHERE `id` = 12;
UPDATE `tblpackages` SET `Description` = 'Take the BP Highway down to Mithila country for darshan at Janaki Mandir, Ram Mandir and the sacred ponds. The trip includes an evening at the aarati.\n\nJanakpur is about 6 to 7 hours from Kathmandu via the BP Highway. Day 2 is set aside for Janaki Mandir, Ram Mandir, Dhanush Sagar and Vivah Mandap, with the evening aarati at Janaki Mandir. Day 3 is the drive home. The driver\'s food and accommodation are included.' WHERE `id` = 13;
UPDATE `tblpackages` SET `Description` = 'An experienced mountain driver takes you from Pokhara through Jomsom and Kagbeni for darshan at Muktinath. You stay overnight in apple-growing Marpha on the way down.\n\nThe trip starts and ends in Pokhara; add a Kathmandu to Pokhara transfer if you need one. The road above Beni is rough and unpaved in places, so the trip uses a 4WD SUV with a driver who knows the route. Nepali citizens don\'t need an ACAP permit, but foreign visitors must buy one before the trip. Muktinath is at about 3,700 m, so take it slowly.' WHERE `id` = 14;
UPDATE `tblpackages` SET `Description` = 'Arrive in style with floral decoration and a driver who keeps to your programme. Convoys and premium decoration are available on request.\n\nThe booking covers 6 hours and 50 km inside the valley, which is enough for most janti processions and photo stops. Choose a sedan or an SUV; luxury and vintage cars are available on request. Overtime is charged by the hour.' WHERE `id` = 15;
UPDATE `tblpackages` SET `Description` = 'Cover staff commutes, client visits and airport runs with a single monthly contract. Maintenance, insurance and a replacement car are all handled by Rento.\n\nThe contract covers 26 working days of up to 10 hours with a dedicated driver. Fuel is billed at actual cost or per km, as agreed in the contract. Parking, tolls and driver overtime are added to the monthly invoice.' WHERE `id` = 16;
